import {
	type CodexOAuthClient,
	GPT_IMAGE_MODELS,
	isGptImageModel,
} from "../../openai-oauth-core/src/index.js"
import { copyUpstreamResponse, isRecord, toErrorResponse } from "./shared.js"

export type ImageEndpoint = "/images/generations" | "/images/edits"

const invalidModelResponse = (): Response =>
	toErrorResponse(`\`model\` must be one of: ${GPT_IMAGE_MODELS.join(", ")}.`)

const validateImageModel = async (
	body: Blob,
	contentType: string | null,
	endpoint: ImageEndpoint,
): Promise<Response | undefined> => {
	if (endpoint === "/images/generations") {
		if (!contentType?.toLowerCase().startsWith("application/json")) {
			return toErrorResponse(
				"Image generation requests must use application/json.",
			)
		}

		let value: unknown
		try {
			value = JSON.parse(await body.text())
		} catch {
			return toErrorResponse("Request body must be valid JSON.")
		}

		return isRecord(value) && isGptImageModel(value.model)
			? undefined
			: invalidModelResponse()
	}

	if (!contentType?.toLowerCase().startsWith("multipart/form-data")) {
		return toErrorResponse("Image edit requests must use multipart/form-data.")
	}

	let form: FormData
	try {
		form = await new Response(body, {
			headers: { "content-type": contentType },
		}).formData()
	} catch {
		return toErrorResponse("Request body must be valid multipart form data.")
	}

	return isGptImageModel(form.get("model")) ? undefined : invalidModelResponse()
}

export const handleImageRequest = async (
	request: Request,
	client: CodexOAuthClient,
	endpoint: ImageEndpoint,
): Promise<Response> => {
	const headers = new Headers()
	const contentType = request.headers.get("content-type")
	const accept = request.headers.get("accept")
	const body = await request.blob()
	const validationError = await validateImageModel(body, contentType, endpoint)
	if (validationError) {
		return validationError
	}

	if (contentType) {
		headers.set("content-type", contentType)
	}
	if (accept) {
		headers.set("accept", accept)
	}

	const upstream = await client.request(endpoint, {
		method: "POST",
		headers,
		body,
		signal: request.signal,
	})

	return copyUpstreamResponse(upstream)
}
